# Deletes the branches listed as DELETE in branch-disposition.tsv (9 Nov 2026).
# Each delete is guarded by --force-with-lease on the exact tip recorded on 9 Nov:
# if anyone pushed to a branch since, git refuses that one delete and leaves the branch alone.
# Needs only git and your normal GitHub sign-in. Run from any folder: it makes a temporary empty repo.
$ErrorActionPreference = "Continue"
$tmp = Join-Path $env:TEMP ("munaxa-branch-cleanup-" + [guid]::NewGuid())
New-Item -ItemType Directory -Path $tmp | Out-Null
Push-Location $tmp
git init -q
